{

"kind": "propose",
"summary": "Renderer container is throttled at CPU limit, causing liveness probe failures. Raise its CPU limit to 1.5 cores.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Renderer is throttled at 1 CPU limit (usage 0.93), with 41% throttling ratio, causing liveness failures.",
    "supporting": ["ev-container_cpu", "ev-target_events"],
    "contradicting": [],
    "missing": ["container_logs_tail"],
    "status": "supported"
  },
  {
    "root_cause_class": "new_version_uses_more_cpu",
    "summary": "Current revision 4 may use more CPU than previous, but rollout_recent is false and earlier_revision_healthy is unknown.",
    "supporting": ["ev-rollout_history"],
    "contradicting": ["rollout_recent"],
    "missing": ["earlier_revision_healthy"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "reports",
    "uid": "uid-deployment-reports"
  },
  "params": {
    "containers": {
      "renderer": {
        "limits": {
          "cpu": "1500m"
        }
      }
    }
  },
  "expected_effect": "Raise renderer's CPU limit from 1 to 1.5 cores to clear throttling and prevent liveness probe timeouts.",
  "rationale": "Throttling_data_available is true, cpu_throttled_at_limit and cpu_usage_near_limit are true, and liveness failures correlate with throttling. No node-level contention or recent rollout indicates the limit is the root cause.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-target_events", "ev-rollout_history"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_recent"]
}
}
